#!/bin/sh
# One-time TEST-only bootstrap of the schema-aware CONTROL worker 4.1.1.
# DOES NOT migrate SQL, change API, enable Firebase, or touch production.
# Run on Synology DSM as a privileged Task Scheduler job from a checksummed
# package generated by package-control-bootstrap.py.
set -eu
umask 077
PATH=/usr/local/bin:/usr/bin:/bin:/var/packages/ContainerManager/target/usr/bin:$PATH
export PATH

INSTALL=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
STATE=/volume2/docker/samosval-test-control/state
LOCK=/volume2/docker/samosval-test-control/worker-upgrade.lock
STAMP=$(date +%Y%m%d%H%M%S)
OLDTAG="samosval-test-control:worker-backup-$STAMP"
NEWIMAGE="samosval-test-control:4.1.1"
PREV_WORKER=
SWITCHED=0

if command -v docker-compose >/dev/null 2>&1; then
  compose() { docker-compose "$@"; }
else
  compose() { docker compose "$@"; }
fi
mkdir -p "$STATE"
mkdir "$LOCK" || { printf 'WORKER_UPGRADE_BUSY\n'; exit 1; }
rollback() {
  code=$?
  trap - EXIT
  if test "$code" -ne 0 && test "$SWITCHED" -eq 1; then
    printf 'WORKER_UPGRADE_ROLLBACK\n'
    # The old worker image remains available under a private rollback tag.
    printf 'services:\n  control:\n    image: %s\n' "$OLDTAG" > "$STATE/worker-rollback.yaml"
    compose -p samosval-test-control -f "$INSTALL/compose.control.test.yaml" \
      -f "$STATE/worker-rollback.yaml" up -d --no-deps --no-build --force-recreate control \
      || printf 'WORKER_ROLLBACK_MANUAL_INTERVENTION_REQUIRED\n'
  fi
  rmdir "$LOCK"
  exit "$code"
}
trap rollback EXIT
cd "$INSTALL"
sha256sum -c SHA256SUMS >/dev/null

if test ! -f "$STATE/installed.json"; then
  printf 'TEST_CONTROL_NOT_INSTALLED\n'; exit 1
fi
if test ! -f "$STATE/baseline.json"; then
  printf 'TEST_SCHEMA_BASELINE_MISSING\n'; exit 1
fi
API=$(docker ps -q --filter label=com.docker.compose.project=samosval-test-candidate \
  --filter label=com.docker.compose.service=api)
PG=$(docker ps -q --filter label=com.docker.compose.project=samosval-test \
  --filter label=com.docker.compose.service=postgres)
CTRL=$(docker ps -q --filter label=com.docker.compose.project=samosval-test-control \
  --filter label=com.docker.compose.service=control)
test "$(printf '%s\n' "$API" | wc -w)" -eq 1
test "$(printf '%s\n' "$PG" | wc -w)" -eq 1
test "$(printf '%s\n' "$CTRL" | wc -w)" -eq 1
docker exec "$PG" sh -c 'test "$POSTGRES_DB" = samosval_test'

APIID=$(docker inspect --format '{{.Image}}' "$API")
PREV_WORKER=$(docker inspect --format '{{.Image}}' "$CTRL")
printf '%s' "$APIID" | grep -Eq '^sha256:[a-f0-9]{64}$'
printf '%s' "$PREV_WORKER" | grep -Eq '^sha256:[a-f0-9]{64}$'
docker image tag "$PREV_WORKER" "$OLDTAG"
# Use the EXACT currently-installed API image as an immutable worker base.
docker image tag "$APIID" samosval-test-api:worker-base-411
docker build --network none -f updater/Dockerfile \
  --build-arg API_BASE=samosval-test-api:worker-base-411 \
  -t "$NEWIMAGE" .
docker run --rm --network none --read-only --entrypoint node "$NEWIMAGE" \
  --check updater/agent.mjs
docker run --rm --network none --read-only --entrypoint node "$NEWIMAGE" \
  --check updater/release.mjs
docker run --rm --network none --entrypoint docker "$NEWIMAGE" compose version

# Only the independent worker is recreated. No API deployment, migrations
# or database restores happen during this first step.
STARTED=$(date +%s)
SWITCHED=1
compose -p samosval-test-control -f "$INSTALL/compose.control.test.yaml" \
  up -d --no-deps --no-build --force-recreate control

READY=0
i=0
while test "$i" -lt 40; do
  # Verify a NEW heartbeat in the existing TEST control table.
  COUNT=$(docker exec "$PG" sh -c 'psql -X -U "$POSTGRES_USER" -d samosval_test -At \
    -c "SELECT count(*) FROM server_control_state WHERE channel=chr(116)||chr(101)||chr(115)||chr(116) \
    AND heartbeat>=to_timestamp($1)"' sh "$STARTED" 2>/dev/null) || COUNT=0
  if test "$COUNT" = 1; then READY=1; break; fi
  sleep 2
  i=$((i+1))
done
if test "$READY" -ne 1; then printf 'WORKER_HEARTBEAT_NOT_CONFIRMED\n'; exit 1; fi
SWITCHED=0
printf 'TEST_CONTROL_WORKER_411_READY\n'
